# Let me identify rectangular outline structures of color 5
# A rectangular outline has boundary cells of one color, interior of another

def find_rectangular_boxes(color, grid):
    """Find all rectangular outlines of a given color"""
    h, w = len(grid), len(grid[0])
    boxes = []

    # Scan all possible top-left corners
    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] != color:
                continue
            for r2 in range(r1 + 1, h):
                for c2 in range(c1 + 1, w):
                    if grid[r2][c2] != color:
                        continue
                    # Check if this forms a valid rectangular boundary
                    is_boundary = True
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            if grid[r][c] != color:
                                is_boundary = False
                                break
                        if not is_boundary:
                            break

                    if is_boundary and r2 - r1 < h/2 and c2 - c1 < w/2:
                        # Check if interior is at least 1x1
                        interior_cells = 0
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                interior_cells += 1

            # More careful check for hollow boxes
            if grid[r1][c1] == color and grid[r2][c2] == color:
                # Check top and bottom edges
                top_ok = all(grid[r1][c] == color for c in range(c1, c2 + 1))
                bottom_ok = all(grid[r2][c] == color for c in range(c1, c2 + 1))
                left_ok = all(grid[r][c1] == color for r in range(r1, r2 + 1))
                right_ok = all(grid[r][c2] == color for r in range(r1, r2 + 1))

                if top_ok and bottom_ok and left_ok and right_ok:
                    # Check interior is uniform (not this color)
                    interior_uniform = grid[r1+1][c1+1] != color if r2 - r1 > 1 and c2 - c1 > 1 else True

                    if top_ok and bottom_ok and left_ok and right_ok and interior_uniform:
                        boxes.append(((r1, c1), (r2, c2)))

    return boxes

