from collections import defaultdict

def find_hollow_shell(grid, shell_color):
    """Find all cells that form the minimal enclosing rectangle of a region"""
    h, w = len(grid), len(grid[0])
    non_shell = defaultdict(list)

    # Find all positions of shell_color
    shell_positions = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == shell_color:
                shell_positions.add((r, c))

    # Find bounding box of shell
    if not shell_positions:
        return []

    min_r = min(r for r, c in shell_positions)
    max_r = max(r for r, c in shell_positions)
    min_c = min(c for r, c in shell_positions)
    max_c = max(c for r, c in shell_positions)

    # Check if this forms a hollow outline
    is_hollow = True
    interior_example = grid[min_r+1][min_c+1] if min_r+1 < h and min_c+1 < w else None

    # Check top, bottom, left, right edges
    for c in range(min_c, max_c+1):
        if grid[min_r][c] != shell_color:
            is_hollow = False
            break
    for c in range(min_c, max_c+1):
        if grid[max_r][c] != shell_color:
            is_hollow = False
            break
    for r in range(min_r, max_r+1):
        if grid[r][min_c] != shell_color:
            is_hollow = False
            break
    for r in range(min_r, max_r+1):
        if grid[r][max_c] != shell_color:
