# Let me create a helper to visualize 5-boundary rectangles
def find_complete_rectangular_hollows(grid, boundary_color=5):
    """Find all complete hollow rectangles of boundary_color"""
    h, w = len(grid), len(grid[0])
    hollows = []

    # Scan each possible top-left
    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] != boundary_color:
                continue
            # Extend to find bottom-right
            for r2 in range(r1, h):
                for c2 in range(c1, w):
                    if grid[r2][c2] != boundary_color:
                        continue

                    # Check if top row is all boundary
                    top_ok = all(grid[r1][c] == boundary_color for c in range(c1, c2 + 1))
                    # Check bottom row is all boundary  
                    bottom_ok = all(grid[r2][c] == boundary_color for c in range(c1, c2 + 1))
                    # Check left col is all boundary
                    left_ok = all(grid[r][c1] == boundary_color for r in range(r1, r2 + 1))
                    # Check right col is all boundary
                    right_ok = all(grid[r][c2] == boundary_color for r in range(r1, r2 + 1))

                    if top_ok and bottom_ok and left_ok and right_ok:
                        # Check interior doesn't contain boundary
                        interior_clear = True
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                if grid[r][c] == boundary_color:
                                    interior_clear = False
                                    break
                            if not interior_clear:
                                break

                        if interior_clear and (r2 - r1 >= 2 and c2 - c1 >= 2):
                            hollows.append(((r1, c1), (r2, c2), r2 - r1 + 1, c2 - c1 + 1))

    # Deduplicate (find minimal boxes)
    hollows = []
    processed = set()
    for (r1,c1), (r2,c2), h, w in hollows:
        key = (r1, c1, r2, c2)
        if key not in processed:
            # Check if this box contains other valid boxes
            is_minimal = True
            for (r1b, c1b), (r2b, c2b), hb, wb in hollows:
                if (r1b, c1b) != (r1, c1) and (r1b, c1b) != (r2, c2):
                    # Check if this is inside another
                    if (r1b <= r1 and c1b <= c1 and r2b >= r2 and c2b >= c2):
                        if (r1b, c1b) != (r1, c1) or (r2b, c2b) != (r2, c2):
                            is_minimal = False
                            break
            if is_minimal:
                hollows.append(((r1, c1), (r2, c2), h, w))
                processed.add(key)

    return hollows

